#!/bin/sh
# Regenerate snippets.js — embedded copies of neo4j/queries/*.cypher and
# typedb/queries/*.tql so the deck also works from file:// (no web server).
# Run this after editing any query file.
cd "$(dirname "$0")"
python3 - <<'EOF'
import json, pathlib
snips = {str(p): p.read_text()
         for pat in ("neo4j/queries/*", "typedb/queries/*", "neo4j/queries/fragments/*", "typedb/queries/fragments/*")
         for p in sorted(pathlib.Path().glob(pat))
         if p.suffix in (".cypher", ".tql")}
pathlib.Path("snippets.js").write_text(
    "// generated by build-snippets.sh — do not edit; edit the query files\n"
    "window.SNIPPETS = " + json.dumps(snips, indent=1) + ";\n")
print(f"snippets.js: {len(snips)} snippets embedded")
EOF
